// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
        // initialize via low-level call to avoid naming C's interface types;
        // this sets the stored owner to the deployer (this test contract)
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "initialize(address,address,address,address,address,address)",
                address(new Stub()),
                address(new Stub()),
                address(new Stub()),
                address(new GlpManagerStub()),
                address(new Stub()),
                address(new Stub())
            )
        );
        require(ok, "init failed");
    }

    function testFuzz_property(address actor, uint256 thresholdBps) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));

        // The stored owner is the deployer (address(this)); any other caller
        // must be rejected by the onlyOwner gate on setThresholds.
        vm.prank(actor);
        bool ok;
        try c.setThresholds(thresholdBps) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "onlyOwner must reject non-owner callers");
    }
}

contract Stub {}

contract GlpManagerStub {
    address public vault;
    constructor() {
        vault = address(new Stub());
    }
}
